import java.util.*;

class MajorityChecker {
  private final int n;
  private final int[] cand, surplus; // Boyer-Moore (candidate, surplus) of each segment-tree node
  private final Map<Integer, List<Integer>> positions = new HashMap<>();

  public MajorityChecker(int[] arr) {
    n = arr.length;
    cand = new int[4 * n];
    surplus = new int[4 * n];
    for (int i = 0; i < n; i++) positions.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
    build(arr, 1, 0, n - 1);
  }

  private void build(int[] a, int node, int lo, int hi) {
    if (lo == hi) {
      cand[node] = a[lo];
      surplus[node] = 1;
      return;
    }
    int mid = (lo + hi) >>> 1;
    build(a, 2 * node, lo, mid);
    build(a, 2 * node + 1, mid + 1, hi);
    int[] m = merge(new int[] {cand[2 * node], surplus[2 * node]}, new int[] {cand[2 * node + 1], surplus[2 * node + 1]});
    cand[node] = m[0];
    surplus[node] = m[1];
  }

  // a value holding a strict majority of the range always survives this merge
  private static int[] merge(int[] a, int[] b) {
    if (a[0] == b[0]) return new int[] {a[0], a[1] + b[1]};
    return a[1] >= b[1] ? new int[] {a[0], a[1] - b[1]} : new int[] {b[0], b[1] - a[1]};
  }

  private int[] candidate(int node, int lo, int hi, int left, int right) {
    if (left <= lo && hi <= right) return new int[] {cand[node], surplus[node]};
    int mid = (lo + hi) >>> 1;
    if (right <= mid) return candidate(2 * node, lo, mid, left, right);
    if (left > mid) return candidate(2 * node + 1, mid + 1, hi, left, right);
    return merge(candidate(2 * node, lo, mid, left, right), candidate(2 * node + 1, mid + 1, hi, left, right));
  }

  public int query(int left, int right, int threshold) {
    int c = candidate(1, 0, n - 1, left, right)[0];
    List<Integer> list = positions.get(c);
    if (list == null) return -1;
    int count = upperBound(list, right) - lowerBound(list, left);
    return count >= threshold ? c : -1;
  }

  private static int lowerBound(List<Integer> a, int x) {
    int l = 0, r = a.size();
    while (l < r) {
      int m = (l + r) >>> 1;
      if (a.get(m) < x) l = m + 1;
      else r = m;
    }
    return l;
  }

  private static int upperBound(List<Integer> a, int x) {
    int l = 0, r = a.size();
    while (l < r) {
      int m = (l + r) >>> 1;
      if (a.get(m) <= x) l = m + 1;
      else r = m;
    }
    return l;
  }
}
